CREATE TABLE training_recoveries (
    id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,
    tenant_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    workspace_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    job_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    previous_attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    next_attempt_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    checkpoint_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin,
    previous_node_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    next_node_id CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    mode VARCHAR(16) NOT NULL CHECK(mode IN ('checkpoint','restart')),
    requested_by CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    reason VARCHAR(500) NOT NULL CHECK(CHAR_LENGTH(TRIM(reason))>0),
    creation_key CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
    creation_fingerprint VARBINARY(32) NOT NULL CHECK(OCTET_LENGTH(creation_fingerprint)=32),
    created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),
    UNIQUE(tenant_id,workspace_id,job_id,id),
    UNIQUE(job_id,creation_key),
    FOREIGN KEY(tenant_id,workspace_id,job_id) REFERENCES training_jobs(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,job_id,previous_attempt_id) REFERENCES training_attempts(tenant_id,workspace_id,job_id,id),
    FOREIGN KEY(tenant_id,workspace_id,job_id,next_attempt_id) REFERENCES training_attempts(tenant_id,workspace_id,job_id,id),
    FOREIGN KEY(tenant_id,workspace_id,job_id,checkpoint_id) REFERENCES training_checkpoints(tenant_id,workspace_id,job_id,id),
    FOREIGN KEY(tenant_id,workspace_id,previous_node_id) REFERENCES managed_nodes(tenant_id,workspace_id,id),
    FOREIGN KEY(tenant_id,workspace_id,next_node_id) REFERENCES managed_nodes(tenant_id,workspace_id,id),
    CHECK((mode='checkpoint')=(checkpoint_id IS NOT NULL)),
    FOREIGN KEY(requested_by) REFERENCES users(id),
    CONSTRAINT training_recoveries_id_canonical CHECK(REGEXP_LIKE(id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_tenant_id_canonical CHECK(REGEXP_LIKE(tenant_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_workspace_id_canonical CHECK(REGEXP_LIKE(workspace_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_job_id_canonical CHECK(REGEXP_LIKE(job_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_previous_attempt_id_canonical CHECK(previous_attempt_id IS NULL OR REGEXP_LIKE(previous_attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_next_attempt_id_canonical CHECK(next_attempt_id IS NULL OR REGEXP_LIKE(next_attempt_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_checkpoint_id_canonical CHECK(checkpoint_id IS NULL OR REGEXP_LIKE(checkpoint_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_previous_node_id_canonical CHECK(REGEXP_LIKE(previous_node_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_next_node_id_canonical CHECK(REGEXP_LIKE(next_node_id,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_requested_by_canonical CHECK(REGEXP_LIKE(requested_by,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c')),
    CONSTRAINT training_recoveries_creation_key_canonical CHECK(REGEXP_LIKE(creation_key,'^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$','c'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_bin;
